const canvas=document.querySelector('#core'),ctx=canvas.getContext('2d');let w,h,angle=0,paused=matchMedia('(prefers-reduced-motion: reduce)').matches,px=0,py=0;const btn=document.querySelector('#motion');function label(){btn.textContent=paused?'Play animation':'Pause animation';btn.setAttribute('aria-pressed',String(paused));document.querySelectorAll('.floating-tag').forEach(e=>e.style.animationPlayState=paused?'paused':'running')}label();btn.onclick=()=>{paused=!paused;label()};function resize(){const r=canvas.getBoundingClientRect();w=r.width;h=r.height;canvas.width=w*devicePixelRatio;canvas.height=h*devicePixelRatio;ctx.setTransform(devicePixelRatio,0,0,devicePixelRatio,0,0)}new ResizeObserver(resize).observe(canvas);canvas.addEventListener('pointermove',e=>{const r=canvas.getBoundingClientRect();px=(e.clientX-r.left)/w-.5;py=(e.clientY-r.top)/h-.5});canvas.addEventListener('pointerleave',()=>{px=py=0});const vertices=[];for(let j=0;j<9;j++){const phi=Math.PI*(j+.5)/9;for(let i=0;i<16;i++){const theta=i/16*Math.PI*2;vertices.push([Math.sin(phi)*Math.cos(theta),Math.cos(phi),Math.sin(phi)*Math.sin(theta)])}}function frame(){requestAnimationFrame(frame);if(!w)return;if(!paused)angle+=.003;ctx.clearRect(0,0,w,h);const radius=Math.min(w*.36,h*.34),a=angle+px*.45,b=.32+py*.3;const points=vertices.map(([x,y,z])=>{const xx=x*Math.cos(a)-z*Math.sin(a),zz=x*Math.sin(a)+z*Math.cos(a),yy=y*Math.cos(b)-zz*Math.sin(b),z2=y*Math.sin(b)+zz*Math.cos(b),s=3.6/(3.6-z2);return{x:w/2+xx*radius*s,y:h/2+yy*radius*s,z:z2}});ctx.save();ctx.translate(w/2,h/2);ctx.scale(1,.3);ctx.strokeStyle='#8ea96225';ctx.lineWidth=1;for(let r=1;r<4;r++){ctx.beginPath();ctx.arc(0,0,radius*(1.25+r*.13),0,Math.PI*2);ctx.stroke()}ctx.restore();for(let j=0;j<9;j++)for(let i=0;i<16;i++){const k=j*16+i,p=points[k];for(const n of [j*16+(i+1)%16,...(j<8?[(j+1)*16+i,(j+1)*16+(i+1)%16]:[])]){const q=points[n];ctx.strokeStyle='rgba(190,240,102,'+(.08+(p.z+q.z+2)/4*.45)+')';ctx.lineWidth=.7;ctx.beginPath();ctx.moveTo(p.x,p.y);ctx.lineTo(q.x,q.y);ctx.stroke()}ctx.beginPath();ctx.fillStyle=p.z>0?'#d5ff63':'#6a8245';ctx.arc(p.x,p.y,p.z>0?1.8:1,0,7);ctx.fill()}const glow=ctx.createRadialGradient(w/2,h/2,0,w/2,h/2,radius*.75);glow.addColorStop(0,'#d5ff6320');glow.addColorStop(1,'#d5ff6300');ctx.fillStyle=glow;ctx.fillRect(0,0,w,h)}frame();document.querySelector('#year').textContent=new Date().getFullYear();
